                r := shr(f, r)
            }
            assembly {
                let f := shl(3, gt(r, 0xFF))
                msb := or(msb, f)
                r := shr(f, r)
            }
            assembly {
                let f := shl(2, gt(r, 0xF))
                msb := or(msb, f)
                r := shr(f, r)
            }
            assembly {
                let f := shl(1, gt(r, 0x3))
                msb := or(msb, f)
                r := shr(f, r)
            }
            assembly {
                let f := gt(r, 0x1)
                msb := or(msb, f)
            }

            if (msb >= 128) r = ratio >> (msb - 127);
            else r = ratio << (127 - msb);

            int256 log_2 = (int256(msb) - 128) << 64;

            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(63, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(62, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(61, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(60, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(59, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(58, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(57, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(56, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(55, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(54, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(53, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(52, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(51, f))
                r := shr(f, r)
            }
            assembly {
                r := shr(127, mul(r, r))
                let f := shr(128, r)
                log_2 := or(log_2, shl(50, f))
            }

            int256 log_sqrt10001 = log_2 * 255738958999603826347141; // 128.128 number

            int24 tickLow = int24((log_sqrt10001 - 3402992956809132418596140100660247210) >> 128);
            int24 tickHi = int24((log_sqrt10001 + 291339464771989622907027621153398088495) >> 128);

            tick = tickLow == tickHi ? tickLow : getSqrtRatioAtTick(tickHi) <= sqrtPriceX96 ? tickHi : tickLow;
        }
    }
}

contracts/beanstalk/farm/TokenFacet.sol.content:
/**
 * SPDX-License-Identifier: MIT
 **/

pragma solidity ^0.8.20;

import {LibTractor} from "contracts/libraries/LibTractor.sol";
import "contracts/libraries/Token/LibTransfer.sol";
import "contracts/libraries/Token/LibWeth.sol";
import "contracts/libraries/Token/LibEth.sol";
import "contracts/libraries/Token/LibTokenPermit.sol";
import "contracts/libraries/Token/LibTokenApprove.sol";
import {IERC1155Receiver} from "contracts/interfaces/IERC1155Receiver.sol";
import "../ReentrancyGuard.sol";
import {AppStorage} from "contracts/beanstalk/storage/AppStorage.sol";
import {Invariable} from "contracts/beanstalk/Invariable.sol";

/**
 * @author Publius
 * @title TokenFacet handles transfers of assets
 */
contract TokenFacet is Invariable, IERC1155Receiver, ReentrancyGuard {
    struct Balance {
        uint256 internalBalance;
        uint256 externalBalance;
        uint256 totalBalance;
    }

    using SafeERC20 for IERC20;
    using LibRedundantMath256 for uint256;

    event InternalBalanceChanged(address indexed user, IERC20 indexed token, int256 delta);

    event TokenApproval(
        address indexed owner,
        address indexed spender,
        IERC20 token,
        uint256 amount
    );

    //////////////////////// Transfer ////////////////////////

    /**
     * @notice transfers a token from user to `recipient`.
     * @dev enables transfers between internal and external balances.
     *
     * @param token The token to transfer.
     * @param recipient The recipient of the transfer.
     * @param amount The amount to transfer.
     * @param fromMode The source of token from the sender. See {LibTransfer.From}.
     * @param toMode The destination of token to the recipient. See {LibTransfer.To}.
     */
    function transferToken(
        IERC20 token,
        address recipient,
        uint256 amount,
        LibTransfer.From fromMode,
        LibTransfer.To toMode
    ) external payable fundsSafu noSupplyChange oneOutFlow(address(token)) nonReentrant {
        LibTransfer.transferToken(token, LibTractor._user(), recipient, amount, fromMode, toMode);
    }

    /**
     * @notice transfers a token from `sender` to an `recipient` from Internal balance.
     * @dev differs from transferToken as sender != user.
     */
    function transferInternalTokenFrom(
        IERC20 token,
        address sender,
        address recipient,
        uint256 amount,
        LibTransfer.To toMode
    ) external payable fundsSafu noSupplyChange oneOutFlow(address(token)) nonReentrant {
        LibTransfer.transferToken(
            token,
            sender,
            recipient,
            amount,
            LibTransfer.From.INTERNAL,
            toMode
        );

        if (sender != LibTractor._user()) {
            LibTokenApprove.spendAllowance(sender, LibTractor._user(), token, amount);
        }
    }

    //////////////////////// Transfer ////////////////////////

    /**
     * @notice approves a token for a spender.
     * @dev this approves a token for both internal and external balances.
     */
    function approveToken(
        address spender,
        IERC20 token,
        uint256 amount
    ) external payable fundsSafu noNetFlow noSupplyChange nonReentrant {
        LibTokenApprove.approve(LibTractor._user(), spender, token, amount);
    }

    /**
     * @notice increases approval for a token for a spender.
     */
    function increaseTokenAllowance(
        address spender,
        IERC20 token,
        uint256 addedValue
    ) public virtual fundsSafu noNetFlow noSupplyChange nonReentrant returns (bool) {
        LibTokenApprove.approve(
            LibTractor._user(),
            spender,
            token,
            LibTokenApprove.allowance(LibTractor._user(), spender, token).add(addedValue)
        );
        return true;
    }

    /**
     * @notice decreases approval for a token for a spender.
     */
    function decreaseTokenAllowance(
        address spender,
        IERC20 token,
        uint256 subtractedValue
    ) public virtual fundsSafu noNetFlow noSupplyChange nonReentrant returns (bool) {
        uint256 currentAllowance = LibTokenApprove.allowance(LibTractor._user(), spender, token);
        require(currentAllowance >= subtractedValue, "Silo: decreased allowance below zero");
        LibTokenApprove.approve(
            LibTractor._user(),
            spender,
            token,
            currentAllowance.sub(subtractedValue)
        );
        return true;
    }

    /**
     * @notice returns the allowance for a token for a spender.
     */
    function tokenAllowance(
        address account,
        address spender,
        IERC20 token
    ) public view virtual returns (uint256) {
        return LibTokenApprove.allowance(account, spender, token);
    }

    //////////////////////// Permit ////////////////////////

    /**
     * @notice approves a token for a spender using EIP2612.
     */
    function permitToken(
        address owner,
        address spender,
        address token,
        uint256 value,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external payable fundsSafu noNetFlow noSupplyChange nonReentrant {
        LibTokenPermit.permit(owner, spender, token, value, deadline, v, r, s);
        LibTokenApprove.approve(owner, spender, IERC20(token), value);
    }

    /**
     * @notice returns the current permit nonce for a token for an owner.
     */
    function tokenPermitNonces(address owner) public view virtual returns (uint256) {
        return LibTokenPermit.nonces(owner);
    }

    //////////////////////// ERC1155Receiver ////////////////////////

    /**
     * @notice ERC1155Receiver function that allows the silo to receive ERC1155 tokens.
     *
     * @dev as ERC1155 deposits are not accepted yet,
     * this function will revert.
     */
    function onERC1155Received(
        address,
        address,
        uint256,
        uint256,
        bytes calldata
    ) external pure override returns (bytes4) {
        revert("Silo: ERC1155 deposits are not accepted yet.");
    }

    /**
     * @notice onERC1155BatchReceived function that allows the silo to receive ERC1155 tokens.
     *
     * @dev as ERC1155 deposits are not accepted yet,
     * this function will revert.
     */
    function onERC1155BatchReceived(
        address,
        address,
        uint256[] calldata,
        uint256[] calldata,
        bytes calldata
    ) external pure override returns (bytes4) {
        revert("Silo: ERC1155 deposits are not accepted yet.");
    }

    /**
     * @dev See {IERC20Permit-DOMAIN_SEPARATOR}.
     */
    // solhint-disable-next-line func-name-mixedcase
    function tokenPermitDomainSeparator() external view returns (bytes32) {
        return LibTokenPermit._domainSeparatorV4();
    }

    //////////////////////// WETH ////////////////////////

    /**
     * @notice wraps ETH into WETH.
     */
    function wrapEth(
        uint256 amount,
        LibTransfer.To mode
    ) external payable nonReentrant fundsSafu noOutFlow noSupplyChange {
        LibWeth.wrap(amount, mode);
        LibEth.refundEth();
    }

    /**
     * @notice unwraps WETH into ETH.
     */
    function unwrapEth(
        uint256 amount,
        LibTransfer.From mode
    ) external payable nonReentrant fundsSafu oneOutFlow(LibWeth.WETH) noSupplyChange {
        LibWeth.unwrap(amount, mode);
    }

    //////////////////////// GETTERS ////////////////////////

    /**
     * @notice returns the internal balance of a token for an account.
     */
    function getInternalBalance(
        address account,
        IERC20 token
    ) public view returns (uint256 balance) {
        balance = LibBalance.getInternalBalance(account, token);
    }

    /**
     * @notice returns the internal balances of tokens for an account.
     */
    function getInternalBalances(
        address account,
        IERC20[] memory tokens
    ) external view returns (uint256[] memory balances) {
        balances = new uint256[](tokens.length);
        for (uint256 i; i < tokens.length; ++i) {
            balances[i] = getInternalBalance(account, tokens[i]);
        }
    }

    // External

    /**
     * @notice returns the external balance of a token for an account.
     */
    function getExternalBalance(
        address account,
        IERC20 token
    ) public view returns (uint256 balance) {
        balance = token.balanceOf(account);
    }

    /**
     * @notice returns the external balances of tokens for an account.
     */
    function getExternalBalances(
        address account,
        IERC20[] memory tokens
    ) external view returns (uint256[] memory balances) {
        balances = new uint256[](tokens.length);
        for (uint256 i; i < tokens.length; ++i) {
            balances[i] = getExternalBalance(account, tokens[i]);
        }
    }

    /**
     * @notice returns the total balance (internal and external)
     * of a token
     */
    function getBalance(address account, IERC20 token) public view returns (uint256 balance) {
        balance = LibBalance.getBalance(account, token);
    }

    /**
     * @notice returns the total balances (internal and external)
     * of a token for an account.
     */
    function getBalances(
        address account,
        IERC20[] memory tokens
    ) external view returns (uint256[] memory balances) {
        balances = new uint256[](tokens.length);
        for (uint256 i; i < tokens.length; ++i) {
            balances[i] = getBalance(account, tokens[i]);
        }
    }

    /**
     * @notice returns the total balance (internal and external)
     * of a token, in a balance struct (internal, external, total).
     */
    function getAllBalance(address account, IERC20 token) public view returns (Balance memory b) {
        b.internalBalance = getInternalBalance(account, token);
        b.externalBalance = getExternalBalance(account, token);
        b.totalBalance = b.internalBalance.add(b.externalBalance);
    }

    /**
     * @notice returns the total balance (internal and external)
     * of a token, in a balance struct (internal, external, total).
     */
    function getAllBalances(
        address account,
        IERC20[] memory tokens
    ) external view returns (Balance[] memory balances) {
        balances = new Balance[](tokens.length);
        for (uint256 i; i < tokens.length; ++i) {
            balances[i] = getAllBalance(account, tokens[i]);
        }
    }
}

contracts/beanstalk/Invariable.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.20;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {LibRedundantMath256} from "contracts/libraries/LibRedundantMath256.sol";
import {LibRedundantMathSigned256} from "contracts/libraries/LibRedundantMathSigned256.sol";
import {SafeCast} from "@openzeppelin/contracts/utils/math/SafeCast.sol";

import {GerminationSide} from "contracts/beanstalk/storage/System.sol";
import {LibAppStorage, AppStorage} from "contracts/libraries/LibAppStorage.sol";
import {LibWhitelistedTokens} from "contracts/libraries/Silo/LibWhitelistedTokens.sol";
import {LibUnripe} from "contracts/libraries/LibUnripe.sol";
import {BeanstalkERC20} from "contracts/tokens/ERC20/BeanstalkERC20.sol";

/**
 * @author funderbrker
 * @title Invariable
 * @notice Implements modifiers that maintain protocol wide invariants.
 * @dev Every external writing function should use as many non-redundant invariant modifiers as possible.
 * @dev https://www.nascent.xyz/idea/youre-writing-require-statements-wrong
 **/
abstract contract Invariable {
    using LibRedundantMath256 for uint256;
    using LibRedundantMathSigned256 for int256;
    using SafeCast for uint256;

    /**
     * @notice Ensures all user asset entitlements are coverable by contract balances.
     * @dev Should be used on every function that can write. Excepting Diamond functions.
     */
    modifier fundsSafu() {
        _;
        address[] memory tokens = getTokensOfInterest();
        (
            uint256[] memory entitlements,
            uint256[] memory balances
        ) = getTokenEntitlementsAndBalances(tokens);
        for (uint256 i; i < tokens.length; i++) {
            require(balances[i] >= entitlements[i], "INV: Insufficient token balance");
        }
    }

    /**
     * @notice Watched token balances do not change and Stalk does not decrease.
     * @dev Applicable to the majority of functions, excepting functions that explicitly move assets.
     * @dev Roughly akin to a view only check where only routine modifications are allowed (ie mowing).
     */
    modifier noNetFlow() {
        uint256 initialStalk = LibAppStorage.diamondStorage().sys.silo.stalk;
        address[] memory tokens = getTokensOfInterest();
        uint256[] memory initialProtocolTokenBalances = getTokenBalances(tokens);
        _;
        uint256[] memory finalProtocolTokenBalances = getTokenBalances(tokens);

        require(
            LibAppStorage.diamondStorage().sys.silo.stalk >= initialStalk,
            "INV: noNetFlow Stalk decreased"
        );
        for (uint256 i; i < tokens.length; i++) {
            require(
                initialProtocolTokenBalances[i] == finalProtocolTokenBalances[i],
                "INV: noNetFlow Token balance changed"
            );
        }
    }

    /**
     * @notice Watched token balances do not decrease and Stalk does not decrease.
     * @dev Favor noNetFlow where applicable.
     */
    modifier noOutFlow() {
        uint256 initialStalk = LibAppStorage.diamondStorage().sys.silo.stalk;
        address[] memory tokens = getTokensOfInterest();
        uint256[] memory initialProtocolTokenBalances = getTokenBalances(tokens);
        _;
        uint256[] memory finalProtocolTokenBalances = getTokenBalances(tokens);

        require(
            LibAppStorage.diamondStorage().sys.silo.stalk >= initialStalk,
            "INV: noOutFlow Stalk decreased"
        );
        for (uint256 i; i < tokens.length; i++) {
            require(
                initialProtocolTokenBalances[i] <= finalProtocolTokenBalances[i],
                "INV: noOutFlow Token balance decreased"
            );
        }
    }

    /**
     * @notice All except one watched token balances do not decrease.
     * @dev Favor noNetFlow or noOutFlow where applicable.
     */
    modifier oneOutFlow(address outboundToken) {
        address[] memory tokens = getTokensOfInterest();
        uint256[] memory initialProtocolTokenBalances = getTokenBalances(tokens);
        _;
        uint256[] memory finalProtocolTokenBalances = getTokenBalances(tokens);

        for (uint256 i; i < tokens.length; i++) {
            if (tokens[i] == outboundToken) {
                continue;
            }
            require(
                initialProtocolTokenBalances[i] <= finalProtocolTokenBalances[i],
                "INV: oneOutFlow multiple token balances decreased"
            );
        }
    }

    /**
     * @notice Does not change the supply of Beans. No minting, no burning.
     * @dev Applies to all but a very few functions tht explicitly change supply.
     */
    modifier noSupplyChange() {
        // Storage is not defined due to stack too deep errors.
        uint256 initialSupply = BeanstalkERC20(LibAppStorage.diamondStorage().sys.tokens.bean)
            .totalSupply();
        _;
        require(
            BeanstalkERC20(LibAppStorage.diamondStorage().sys.tokens.bean).totalSupply() ==
                initialSupply,
            "INV: Supply changed"
        );
    }

    /**
     * @notice Supply of Beans does not increase. No minting.
     * @dev Prefer noSupplyChange where applicable.
     */
    modifier noSupplyIncrease() {
        uint256 initialSupply = BeanstalkERC20(LibAppStorage.diamondStorage().sys.tokens.bean)
            .totalSupply();
        _;
        require(
            BeanstalkERC20(LibAppStorage.diamondStorage().sys.tokens.bean).totalSupply() <=
                initialSupply,
            "INV: Supply increased"
        );
    }

    /**
     * @notice Which tokens to monitor in the invariants.
     */
    function getTokensOfInterest() internal view returns (address[] memory tokens) {
        address[] memory whitelistedTokens = LibWhitelistedTokens.getWhitelistedTokens();
        address[] memory sopTokens = LibWhitelistedTokens.getSopTokens();
        uint256 totalLength = whitelistedTokens.length + sopTokens.length;
        tokens = new address[](totalLength);

        for (uint256 i = 0; i < whitelistedTokens.length; i++) {
            tokens[i] = whitelistedTokens[i];
        }

        for (uint256 i = 0; i < sopTokens.length; i++) {
            tokens[whitelistedTokens.length + i] = sopTokens[i];
        }
    }

    /**
     * @notice Get the Beanstalk balance of an ERC20 token.
     */
    function getTokenBalances(
        address[] memory tokens
    ) internal view returns (uint256[] memory balances) {
        balances = new uint256[](tokens.length);
        for (uint256 i; i < tokens.length; i++) {
            balances[i] = IERC20(tokens[i]).balanceOf(address(this));
        }
        return balances;
    }

    /**
     * @notice Get protocol level entitlements and balances for all tokens.
     */
    function getTokenEntitlementsAndBalances(
        address[] memory tokens
    ) internal view returns (uint256[] memory entitlements, uint256[] memory balances) {
        AppStorage storage s = LibAppStorage.diamondStorage();
        entitlements = new uint256[](tokens.length);
        balances = new uint256[](tokens.length);

        for (uint256 i; i < tokens.length; i++) {
            entitlements[i] =
                s.sys.silo.balances[tokens[i]].deposited +
                s.sys.silo.germinating[GerminationSide.ODD][tokens[i]].amount +
                s.sys.silo.germinating[GerminationSide.EVEN][tokens[i]].amount +
                s.sys.internalTokenBalanceTotal[IERC20(tokens[i])];
            if (tokens[i] == s.sys.tokens.bean) {
                entitlements[i] +=
                    (s.sys.fert.fertilizedIndex -
                        s.sys.fert.fertilizedPaidIndex +
                        s.sys.fert.leftoverBeans) + // unrinsed rinsable beans
                    s.sys.silo.unripeSettings[s.sys.tokens.urBean].balanceOfUnderlying + // unchopped underlying beans
                    s.sys.orderLockedBeans;
                for (uint256 j; j < s.sys.fieldCount; j++) {
                    entitlements[i] += (s.sys.fields[j].harvestable - s.sys.fields[j].harvested); // unharvested harvestable beans
                }
            } else if (tokens[i] == LibUnripe._getUnderlyingToken(s.sys.tokens.urLp)) {
                entitlements[i] += s.sys.silo.unripeSettings[s.sys.tokens.urLp].balanceOfUnderlying;
            }
            entitlements[i] += s.sys.sop.plentyPerSopToken[tokens[i]];
            balances[i] = IERC20(tokens[i]).balanceOf(address(this));
        }
        return (entitlements, balances);
    }
}

contracts/beanstalk/ReentrancyGuard.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.20;

import {AppStorage} from "./storage/AppStorage.sol";
import {C} from "contracts/C.sol";

/**
 * @author Beanstalk Farms
 * @title Variation of Oepn Zeppelins reentrant guard to include Beanstalk specific functionality.
 * https://github.com/OpenZeppelin/openzeppelin-contracts/blob/master/contracts%2Fsecurity%2FReentrancyGuard.sol
 *
 * The key difference between Beanstalk reentrancy and standard reentrancy is the need for Beanstalk
 * to be able to re-enter itself executing functions through farm-like functions. This Farm functiiionality
 * allows users to batch multiple Beanstalk functions into a single transaction.
 * Examples of Farm use can be seen in Farm, AdvancedFarm, Tractor, and PipelineConvert.
 * Reference _beanstalkCall() to see Farm interaction with ReentrancyGuard.
 **/
abstract contract ReentrancyGuard {
    AppStorage internal s;

    /**
     * @notice Verify Beanstalk is not already entered and lock entrance.
     * @dev Standard reentrancy is not compatible with farm-like features.
     */
    modifier nonReentrant() {
        require(s.sys.reentrantStatus != C.ENTERED, "ReentrancyGuard: reentrant call");

        s.sys.reentrantStatus = C.ENTERED;
        _;
        s.sys.reentrantStatus = C.NOT_ENTERED;
    }

    /**
     * @notice Verify and lock both standard entrance and farming entrance.
     * @dev This modifier should be used on all functions that contain generalized Farm calls.
     */
    modifier nonReentrantFarm() {
        require(s.sys.farmingStatus != C.ENTERED, "ReentrancyGuard: reentrant farm call");
        require(s.sys.reentrantStatus != C.ENTERED, "ReentrancyGuard: reentrant call");

        s.sys.farmingStatus = C.ENTERED;
        s.sys.reentrantStatus = C.ENTERED;
        _;
        s.sys.farmingStatus = C.NOT_ENTERED;
        s.sys.reentrantStatus = C.NOT_ENTERED;
    }
}

contracts/beanstalk/storage/Account.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {GerminationSide} from "./System.sol";

/**
 * @title Account
 * @notice Stores Farmer-level Beanstalk state.
 * @param roots A Farmer's Root balance.
 * @param stalk Balance of the Farmer's Stalk.
 * @param depositPermitNonces A Farmer's current deposit permit nonce.
 * @param tokenPermitNonces A Farmer's current token permit nonce.
 * @param lastUpdate The Season in which the Farmer last updated their Silo.
 * @param lastSop The last Season that a SOP occurred at the time the Farmer last updated their Silo.
 * @param lastRain The last Season that it started Raining at the time the Farmer last updated their Silo.
 * @param _buffer_0 Reserved storage for future additions.
 * @param deposits SiloV3.1 deposits. A mapping from depositId to Deposit. SiloV3.1 introduces greater precision for deposits.
 * @param depositIdList DepositListData for each token owned by the account.
 * @param field A mapping from FieldId to a Farmer's Field storage.
 * @param depositAllowances A mapping of `spender => Silo token address => amount`.
 * @param tokenAllowances Internal balance token allowances.
 * @param mowStatuses A mapping of whitelisted token address to MowStatus.
 * @param isApprovedForAll A mapping of ERC1155 operator to approved status. ERC1155 compatability.
 * @param germinatingStalk A Farmer's germinating stalk. Separated into odd and even stalk.
 * @param internalTokenBalance A mapping from Token address to Internal Balance. It stores the amount of the Token that the Farmer has stored as an Internal Balance in Beanstalk.
 * @param _buffer_1 Reserved storage for future additions.
 * @param silo A Farmer's Silo storage.
 * @param sop A Farmer's Season of Plenty storage.
 */
struct Account {
    uint256 roots;
    uint256 stalk;
    uint256 depositPermitNonces;
    uint256 tokenPermitNonces;
    uint32 lastUpdate;
    uint32 lastSop;
    uint32 lastRain;
    bytes32[16] _buffer_0;
    mapping(uint256 => Deposit) deposits;
    mapping(address => DepositListData) depositIdList;
    mapping(uint256 => Field) fields;
    mapping(address => mapping(address => uint256)) depositAllowances;
    mapping(address => mapping(IERC20 => uint256)) tokenAllowances;
    mapping(address => MowStatus) mowStatuses;
    mapping(address => bool) isApprovedForAll;
    mapping(GerminationSide => uint128) germinatingStalk;
    mapping(IERC20 => uint256) internalTokenBalance;
    bytes32[16] _buffer_1;
    SeasonOfPlenty sop;
}

/**
 * @notice Stores a Farmer's Plots and Pod allowances.
 * @param plots A Farmer's Plots. Maps from Plot index to Pod amount.
 * @param podAllowances An allowance mapping for Pods similar to that of the ERC-20 standard. Maps from spender address to allowance amount.
 * @param plotIndexes An array of Plot indexes. Used to return the farm plots of a Farmer.
 * @param piIndex A mapping from Plot index to the index in plotIndexes.
 * @param _buffer Reserved storage for future additions.
 */
struct Field {
    mapping(uint256 => uint256) plots;
    mapping(address => uint256) podAllowances;
    uint256[] plotIndexes;
    mapping(uint256 => uint256) piIndex;
    bytes32[4] _buffer;
}

/**
 * @notice Stores a Farmer's Season of Plenty (SOP) balances.
 * @param roots The number of Roots a Farmer had when it started Raining.
 * @param plentyPerRoot The global Plenty Per Root index at the last time a Farmer updated their Silo.
 * @param plenty The balance of a Farmer's plenty. Plenty can be claimed directly for tokens.
 * @param _buffer Reserved storage for future additions.
 */
struct SeasonOfPlenty {
    uint256 rainRoots; // The number of Roots a Farmer had when it started Raining.
    mapping(address => PerWellPlenty) perWellPlenty; // a mapping from well to plentyPerRoot and plenty.
    bytes32[4] _buffer;
}

/**
 * @notice Stores a Farmer's Season of Plenty (SOP) balances.
 * @param plentyPerRoot The Plenty Per Root index for this well at the last time a Farmer updated their Silo.
 * @param plenty The balance of a Farmer's plenty. Plenty can be claimed directly for the well's non-Bean token.
 */
struct PerWellPlenty {
    uint256 plentyPerRoot;
    uint256 plenty;
    bytes32[4] _buffer;
}

/**
 * @notice Represents a Deposit of a given Token in the Silo at a given Season.
 * @param amount The amount of Tokens in the Deposit.
 * @param bdv The Bean-denominated value of the total amount of Tokens in the Deposit.
 * @param _buffer Reserved storage for future additions.
 * @dev `amount` and `bdv` are packed as uint128 to save gas.
 */
struct Deposit {
    uint128 amount;
    uint128 bdv;
}

/**
 * @notice Stores a Farmer's germinating stalk.
 * @param odd - stalk from assets deposited in odd seasons.
 * @param even - stalk from assets deposited in even seasons.
 * @param _buffer Reserved storage for future additions.
 */
struct GerminatingStalk {
    uint128 odd;
    uint128 even;
}

/**
 * @notice This struct stores the mow status for each whitelisted token, for each farmer.
 * This gets updated each time a farmer mows, or adds/removes deposits.
 * @param lastStem The last cumulative grown stalk per bdv index at which the farmer mowed.
 * @param bdv The bdv of all of a farmer's deposits of this token type.
 * @param _buffer Reserved storage for future additions.
 */
struct MowStatus {
    int96 lastStem;
    uint128 bdv;
}

/**
 * @notice This struct stores data for a deposit list for a given token.
 * a mapping from id to index was created to allow for O(1) retrevial of a deposit from the list.
 * @param depositIds An array of depositIds for a given token.
 * @param idIndex A mapping from depositId to index in depositIds.
 */
struct DepositListData {
    uint256[] depositIds;
    mapping(uint256 => uint256) idIndex;
}

