                        }
                    } else if (recapPercentPaid > 0.12e6) {
                        if (recapPercentPaid > 0.13e6) {
                            return 0.7328743482797107e18; // 1,000,000, 0.14
                        } else {
                            return 0.7486234889866461e18; // 1,000,000, 0.13
                        }
                    } else {
